-- Publications and research (spec 054, research R13): the section tree as in Figma (`2698:5000`). Generated by
-- specs/054-publications-research/seed/build-tree-seed.mjs from tree.json — edit those, not this file.
--
-- 1. Two group pages under the root, "Tədqiqatlar" and "Nəşrlər, hesabatlar və sənədlər", created only while missing.
-- 2. The Figma pages move under them in the Figma order, "Rəqəmsal fırıldaqçılıq statistikası" and "Ödəniş xidmətləri"
--    from the consumer rights section; a page moves only while it is still under its legacy parent, and its menu flags
--    are set only then, so an editor's later change stands. Addresses are slugs, so none changes; nothing is deleted.
-- 3. "Ödəniş xidmətləri" is listed only in the dropdown menus (page_nav_details, 0039).
-- 4. The six legacy pages Figma leaves out stay under the root and leave every menu; so does the draft root.
-- 5. Menu group labels (page_translation_details, shown from spec 055), only where a page has none.
-- 6. Figma titles, only over the legacy titles; Figma intros, only over the legacy texts (md5).
-- Pages are found by az slug: ids differ between environments. The "(Kopya)" draft tree keeps its pages and texts; only
-- its root leaves the menus (4), as the consumer section's draft did in 0031.
DO $seed$
DECLARE
    root_id      integer;
    root_path    ltree;
    consumer_id  integer;
    g            record;
    group_id     integer;
    group_path   ltree;
    group_slug   text;
    child_slug   text;
    child_id     integer;
    child_parent integer;
    child_path   ltree;
    new_path     ltree;
    seq          integer;
    created      integer := 0;
    moved        integer := 0;
    changed      integer;
BEGIN
    -- In shared environments the tables may belong to another role (see 0028, 0030, 0031).
    IF NOT has_table_privilege('pages', 'INSERT')
       OR NOT has_table_privilege('pages', 'UPDATE')
       OR NOT has_table_privilege('page_translations', 'INSERT')
       OR NOT has_table_privilege('page_translations', 'UPDATE')
       OR NOT has_table_privilege('page_details', 'INSERT')
       OR NOT has_table_privilege('page_details', 'UPDATE')
       OR NOT has_table_privilege('page_nav_details', 'INSERT')
       OR NOT has_table_privilege('page_translation_details', 'INSERT') THEN
        RAISE WARNING 'spec 054: missing INSERT/UPDATE privileges on the page tables, publications tree seed skipped';
        RETURN;
    END IF;

    SELECT page_id INTO root_id FROM page_translations WHERE locale = 'az' AND slug = 'nesrler-ve-tedqiqatlar';
    IF root_id IS NULL THEN
        RAISE NOTICE 'spec 054: no publications section, tree seed skipped';
        RETURN;
    END IF;
    SELECT path INTO root_path FROM pages WHERE id = root_id;
    SELECT page_id INTO consumer_id FROM page_translations WHERE locale = 'az' AND slug = 'istehlakcilarin-ve-investorlarin-huquqlari';

    FOR g IN
        SELECT * FROM (VALUES
        (1, 'tedqiqatlar', 'research', 'Tədqiqatlar', 'Research',
         $html$<p>Azərbaycan Respublikasının Mərkəzi Bankında aparılan tədqiqat işlərinin əsas məqsədi ölkədə effektiv makroiqtisadi, o cümlədən pul və məzənnə siyasətinin analitik-empirik tədqiqat bazasını formalaşdırmaq, sosial-iqtisadi inkişafı dəstəkləyən makroiqtisadi sabitliyin fundamentallarının aşkarlanmasına töhfə verməkdir. Tədqiqat işləri dövri xarakter daşıyır və mütəmadi olaraq elektron formatda ictimaiyyətə təqdim olunur.</p><p>Tədqiqatların nəticələri ilə “İşçi məqalələr silsiləsi”, qurulmuş modellər və indekslərlə “Ekonometrik modellər” bölməsində, tədqiqat yönümlü əlavə materiallarla “Digər nəşrlər” bölməsində tanış olmaq mümkündür.</p><p>İqtisadiyyat və maliyyə sektoru üzrə aktual məsələlərin araşdırılmasına, nəzəri və empirik qiymətləndirilməsinə həsr olunmuş tədqiqat işləri burada təqdim olunur.</p>$html$,
         $html$<p>The main purpose of the research conducted at the Central Bank of the Republic of Azerbaijan is to build an analytical and empirical research base for effective macroeconomic policy, including monetary and exchange rate policy, and to help identify the fundamentals of macroeconomic stability that support socio-economic development. Research is periodic and regularly published electronically.</p><p>The research results are presented in the “Working paper series”, the models and indices built in the “Econometric models” section, and additional research materials in the “Other publications” section.</p><p>Research papers devoted to the study and the theoretical and empirical assessment of topical issues of the economy and the financial sector are presented here.</p>$html$,
         ARRAY['ekonometrik-modeller', 'isci-meqaleler-silsilesi']),
        (2, 'nesrler-hesabatlar-ve-senedler', 'publications-reports-and-documents', 'Nəşrlər, hesabatlar və sənədlər', 'Publications, reports and documents',
         $html$<p>Mərkəzi Bank tərəfindən hazırlanmış analitik materiallar, dövri hesabatlar, konseptual sənədlər və digər nəşrlər burada təqdim olunur.</p>$html$,
         $html$<p>Analytical materials, periodic reports, conceptual documents and other publications prepared by the Central Bank are presented here.</p>$html$,
         ARRAY['illik-hesabat', 'sahelerarasi-maliyye-axinlarinin-tehlili', 'mikromaliyye-modeli-uzre-strateji-cercive', 'maliyye-bazarlarinda-kibertehlukesizlik-strategiyasi', 'risk-esasli-nezaret-uzre-siyaset-konsepsiyasi', 'nezaret-texnologiyalari-uzre-yol-xeritesi', 'reqemsal-firildaqciliq-statistikasi', 'odenis-xidmetleri'])
        ) AS v (sort, slug_az, slug_en, title_az, title_en, intro_az, intro_en, children)
        ORDER BY sort
    LOOP
        -- 1. The group page: found among the root's children by slug (or its "-2" form), created otherwise.
        SELECT p.id, p.path INTO group_id, group_path
        FROM pages p JOIN page_translations t ON t.page_id = p.id AND t.locale = 'az'
        WHERE p.parent_id = root_id AND p.deleted_at IS NULL AND t.slug IN (g.slug_az, g.slug_az || '-2')
        ORDER BY p.id LIMIT 1;

        IF group_id IS NULL THEN
            -- The groups go first in the root's menu: shift the root's children to make room, keeping their order.
            IF created = 0 THEN
                WITH ordered AS (
                    SELECT id, row_number() OVER (ORDER BY sort_order, id) AS rn FROM pages WHERE parent_id = root_id
                )
                UPDATE pages p SET sort_order = (o.rn + 2) * 10 FROM ordered o WHERE p.id = o.id;
            END IF;
            INSERT INTO pages (parent_id, path, sort_order, status)
            VALUES (root_id, root_path, g.sort * 10, 'published')
            RETURNING id INTO group_id;
            group_path := root_path || text2ltree(group_id::text);
            UPDATE pages SET path = group_path WHERE id = group_id;
            -- A slug taken elsewhere in the locale gets "-2", as SlugService would.
            group_slug := CASE WHEN EXISTS (SELECT FROM page_translations WHERE locale = 'az' AND slug = g.slug_az) THEN g.slug_az || '-2' ELSE g.slug_az END;
            INSERT INTO page_translations (page_id, locale, title, slug, content) VALUES (group_id, 'az', g.title_az, group_slug, g.intro_az);
            group_slug := CASE WHEN EXISTS (SELECT FROM page_translations WHERE locale = 'en' AND slug = g.slug_en) THEN g.slug_en || '-2' ELSE g.slug_en END;
            INSERT INTO page_translations (page_id, locale, title, slug, content) VALUES (group_id, 'en', g.title_en, group_slug, g.intro_en);
            created := created + 1;
        END IF;

        -- 2. The group's pages, in the Figma order, while still under the root or the consumer rights section.
        seq := 0;
        FOREACH child_slug IN ARRAY g.children
        LOOP
            seq := seq + 1;
            child_id := NULL;
            SELECT p.id, p.parent_id, p.path INTO child_id, child_parent, child_path
            FROM pages p JOIN page_translations t ON t.page_id = p.id AND t.locale = 'az' AND t.slug = child_slug
            WHERE p.deleted_at IS NULL;
            IF child_id IS NULL OR child_parent = group_id
               OR child_parent IS DISTINCT FROM root_id AND child_parent IS DISTINCT FROM consumer_id THEN
                CONTINUE;
            END IF;

            new_path := group_path || text2ltree(child_id::text);
            UPDATE pages SET parent_id = group_id, path = new_path, sort_order = seq * 10 WHERE id = child_id;
            UPDATE pages SET path = new_path || subpath(path, nlevel(child_path)) WHERE path <@ child_path AND id <> child_id;
            moved := moved + 1;

            -- The consumer section hid these two (0031). In this section one is listed everywhere, the other only in
            -- the dropdown menus (3).
            IF child_parent = consumer_id THEN
                INSERT INTO page_details (page_id, show_in_side_nav) VALUES (child_id, child_slug <> ALL (ARRAY['odenis-xidmetleri']))
                ON CONFLICT (page_id) DO UPDATE SET show_in_side_nav = EXCLUDED.show_in_side_nav;
                IF child_slug = ANY (ARRAY['odenis-xidmetleri']) THEN
                    INSERT INTO page_nav_details (page_id, show_in_dropdown_nav) VALUES (child_id, true)
                    ON CONFLICT (page_id) DO UPDATE SET show_in_dropdown_nav = true;
                END IF;
            END IF;
        END LOOP;
    END LOOP;
    RAISE NOTICE 'spec 054: % group pages created, % pages moved', created, moved;

    -- 4. Legacy pages outside Figma leave every menu; they stay under the root with their addresses.
    INSERT INTO page_details (page_id, show_in_side_nav)
    SELECT t.page_id, false
    FROM page_translations t JOIN pages p ON p.id = t.page_id AND p.parent_id = root_id
    WHERE t.locale = 'az' AND t.slug = ANY (ARRAY['maliyye-sabitliyi-hesabati', 'bank-sektoru-uzre-makroprudensial-siyaset-cercivesi', 'istehlakcilarin-huquqlarinin-mudafiesi-ve-maliyye-savadliligi', 'dayaniqli-maliyye-uzre-yol-xeritesi', 'kreditlesme-fealiyyeti-ve-maliyyelesme-menbelerine-dair-sorgu', 'maliyye-xidmetleri-sahesinde-tenzimleyici-cercivenin-hazirliq-seviyyesinin-tehlili', 'nesrler-ve-tedqiqatlar-copy'])
    ON CONFLICT (page_id) DO NOTHING;
    GET DIAGNOSTICS changed = ROW_COUNT;
    RAISE NOTICE 'spec 054: % pages left out of the menus', changed;

    -- 5. Menu group labels, where the page has none yet.
    INSERT INTO page_translation_details (page_id, locale, menu_group)
    SELECT az.page_id, v.locale, v.label
    FROM (VALUES
        ('mikromaliyye-modeli-uzre-strateji-cercive', 'az', 'Strategiyalar və konsepsiyalar'),
        ('mikromaliyye-modeli-uzre-strateji-cercive', 'en', 'Strategies and concepts'),
        ('maliyye-bazarlarinda-kibertehlukesizlik-strategiyasi', 'az', 'Strategiyalar və konsepsiyalar'),
        ('maliyye-bazarlarinda-kibertehlukesizlik-strategiyasi', 'en', 'Strategies and concepts'),
        ('risk-esasli-nezaret-uzre-siyaset-konsepsiyasi', 'az', 'Strategiyalar və konsepsiyalar'),
        ('risk-esasli-nezaret-uzre-siyaset-konsepsiyasi', 'en', 'Strategies and concepts'),
        ('nezaret-texnologiyalari-uzre-yol-xeritesi', 'az', 'Strategiyalar və konsepsiyalar'),
        ('nezaret-texnologiyalari-uzre-yol-xeritesi', 'en', 'Strategies and concepts'),
        ('odenis-xidmetleri', 'az', 'Ödəniş sistemləri'),
        ('odenis-xidmetleri', 'en', 'Payment systems')
    ) AS v (az_slug, locale, label)
    JOIN page_translations az ON az.locale = 'az' AND az.slug = v.az_slug
    WHERE EXISTS (SELECT FROM page_translations t WHERE t.page_id = az.page_id AND t.locale = v.locale)
    ON CONFLICT (page_id, locale) DO NOTHING;
    GET DIAGNOSTICS changed = ROW_COUNT;
    RAISE NOTICE 'spec 054: % menu group labels written', changed;

    -- 6a. Figma titles, only over the legacy ones.
    UPDATE page_translations t
    SET title = v.title
    FROM (VALUES
        ('isci-meqaleler-silsilesi', 'az', 'İşçi məqalələr silsiləsi', 'İşçi məqalələri'),
        ('isci-meqaleler-silsilesi', 'en', 'Working paper series', 'Working papers'),
        ('risk-esasli-nezaret-uzre-siyaset-konsepsiyasi', 'az', 'Risk əsaslı nəzarət üzrə Siyasət Konsepsiyası', 'Azərbaycan Respublikası Mərkəzi Bankının risk əsaslı nəzarət üzrə Siyasət Konsepsiyası'),
        ('nezaret-texnologiyalari-uzre-yol-xeritesi', 'az', 'Nəzarət Texnologiyaları üzrə Yol Xəritəsi', 'Azərbaycan Respublikası Mərkəzi Bankının 2024-2029-cu illəri əhatə edəcək Nəzarət Texnologiyaları üzrə Yol Xəritəsinin qısa icmalı')
    ) AS v (az_slug, locale, legacy, title)
    JOIN page_translations az ON az.locale = 'az' AND az.slug = v.az_slug
    WHERE t.page_id = az.page_id AND t.locale = v.locale AND t.title = v.legacy;
    GET DIAGNOSTICS changed = ROW_COUNT;
    RAISE NOTICE 'spec 054: % titles written', changed;

    -- 6b. Figma intros in front of the file link, only over the legacy texts.
    UPDATE page_translations t
    SET content = v.intro || coalesce(t.content, '')
    FROM (VALUES
        ('mikromaliyye-modeli-uzre-strateji-cercive', 'az', '6016e766d2daddfa72123e33f90d4b38', $html$<p>«Mikromaliyyə Modeli üzrə Strateji Çərçivə» “Azərbaycan Respublikasının 2022–2026-cı illərdə sosial-iqtisadi inkişaf Strategiyası”nda maliyyəyə çıxışın təmin edilməsi ilə bağlı nəzərdə tutulan tədbirlərin icrası məqsədilə hazırlanıb. Sənəd özünüməşğul şəxslərin və MKOB-ların münasib şərtlərlə maliyyə xidmətlərinə çıxışının genişləndirilməsini və 2030-cu ilədək çevik, effektiv və inklüziv mikromaliyyə sektorunun formalaşdırılmasını hədəfləyir.</p>$html$),
        ('mikromaliyye-modeli-uzre-strateji-cercive', 'en', 'd2407b1039cfd9d604dbdcff768b3c02', $html$<p>The “Strategic Framework for a Microfinance Model” was prepared to implement the measures on access to finance set out in the “Strategy of Socio-Economic Development of the Republic of Azerbaijan for 2022–2026”. The document aims to broaden access to financial services on affordable terms for the self-employed and MSMEs and to build an agile, effective and inclusive microfinance sector by 2030.</p>$html$),
        ('maliyye-bazarlarinda-kibertehlukesizlik-strategiyasi', 'az', '0cfe46ef5ce0da18661c8905b1aaa585', $html$<p>2023–2026-cı illər üçün “Maliyyə bazarları üzrə kibertəhlükəsizlik Strategiyası” Mərkəzi Bankda və ölkədə fəaliyyət göstərən maliyyə institutlarında informasiya təhlükəsizliyinin və kibertəhlükəsizliyin gücləndirilməsi, müasir dövrün kibertəhlükəsizlik təhdidlərinin və kiberhücumların qarşısının daha effektiv alınması üzrə əsas fəaliyyət istiqamətlərini müəyyən edir. Strategiyanın vizyonu maliyyə sabitliyinin təmin edilməsi üçün artan kibertəhdidlər fonunda ölkənin maliyyə bazarlarında kiber dayanıqlığın gücləndirilməsidir.</p>$html$),
        ('maliyye-bazarlarinda-kibertehlukesizlik-strategiyasi', 'en', '0ec6d8e75e97ddc6cdc294faa6a57fba', $html$<p>The “Cybersecurity Strategy for Financial Markets” for 2023–2026 sets out the main lines of action for strengthening information security and cybersecurity at the Central Bank and the financial institutions operating in the country, and for preventing modern cyber threats and cyberattacks more effectively. The vision of the Strategy is to strengthen cyber resilience in the country’s financial markets against growing cyber threats in order to ensure financial stability.</p>$html$),
        ('risk-esasli-nezaret-uzre-siyaset-konsepsiyasi', 'az', '28c7e741a219dad4a7993f7b8a5ba7b2', $html$<p>“Azərbaycan Respublikası Mərkəzi Bankının risk əsaslı nəzarət üzrə Siyasət Konsepsiyası” “2024–2026-cı illərdə maliyyə sektorunun inkişaf Strategiyası” çərçivəsində hazırlanıb və nəzarət subyektləri üzrə risk əsaslı nəzarət yanaşmasının tətbiqini hədəfləyir. Sənəd Mərkəzi Bankın tətbiq etdiyi ARAS (Azərbaycan Risklərin Qiymətləndirilməsi Sistemi) nəzarət tsiklini, risk reytinqi sistemini və risk əsaslı nəzarətin təşkilati quruluşunu müəyyən edir.</p>$html$),
        ('risk-esasli-nezaret-uzre-siyaset-konsepsiyasi', 'en', 'd41d8cd98f00b204e9800998ecf8427e', $html$<p>The “Risk-Based Supervision Policy Concept of the Central Bank of the Republic of Azerbaijan” was prepared under the “Financial Sector Development Strategy for 2024–2026” and aims to apply a risk-based supervision approach to supervised entities. The document defines the ARAS (Azerbaijan Risk Assessment System) supervisory cycle applied by the Central Bank, the risk rating system and the organisational structure of risk-based supervision.</p>$html$),
        ('nezaret-texnologiyalari-uzre-yol-xeritesi', 'az', '61b3918dfdb3ea91aed59aaad797be0a', $html$<p>Nəzarət Texnologiyaları (SupTech) üzrə Yol Xəritəsi “2024–2026-cı illərdə maliyyə sektorunun inkişaf Strategiyası” çərçivəsində Mərkəzi Bank və Dünya Bankı Qrupu tərəfindən birgə hazırlanıb. Sənəd risk əsaslı nəzarət məqsədilə texnologiya və dataların istifadəsi üzrə gələcək perspektivləri, o cümlədən təkmil analitika, böyük data və təbii dil emalı kimi texnologiyaların tətbiqini, eləcə də 2024–2029-cu illər üçün SupTech layihə və təşəbbüslər portfelini müəyyən edir.</p>$html$),
        ('nezaret-texnologiyalari-uzre-yol-xeritesi', 'en', '71ddaa3a55b2a93049efb56c17cd6017', $html$<p>The Supervision Technologies (SupTech) Road Map was prepared jointly by the Central Bank and the World Bank Group under the “Financial Sector Development Strategy for 2024–2026”. The document sets out the outlook for using technology and data for risk-based supervision, including advanced analytics, big data and natural language processing, as well as the portfolio of SupTech projects and initiatives for 2024–2029.</p>$html$),
        ('odenis-xidmetleri', 'az', '2b7ee0271547e163eb519f623792d7fc', $html$<p>Ölkədə ödəniş xidməti göstərən ödəniş və elektron pul təşkilatları Mərkəzi Bankdan lisenziya almalıdırlar. Təlimatda təşkilatın və ya ödəniş agentinin lisenziyasının Mərkəzi Bankın internet səhifəsindəki reyestrlərdən necə yoxlanılacağı, həmçinin lisenziyasız fəaliyyət aşkar edildikdə bu barədə Mərkəzi Banka “Elektron müraciətlər sistemi” vasitəsilə necə məlumat veriləcəyi addım-addım izah olunur. Məlumat verən şəxsin konfidensiallığına Mərkəzi Bank təminat verir.</p>$html$),
        ('odenis-xidmetleri', 'en', '1127e97cef67f20646837338a43ad167', $html$<p>Payment and electronic money institutions that provide payment services in the country must be licensed by the Central Bank. The guide explains step by step how to check the licence of an institution or a payment agent in the registers on the Central Bank’s website, and how to report unlicensed activity to the Central Bank through the “Electronic appeals system”. The Central Bank guarantees the confidentiality of the person who reports.</p>$html$)
    ) AS v (az_slug, locale, legacy_md5, intro)
    JOIN page_translations az ON az.locale = 'az' AND az.slug = v.az_slug
    WHERE t.page_id = az.page_id AND t.locale = v.locale AND md5(coalesce(t.content, '')) = v.legacy_md5;
    GET DIAGNOSTICS changed = ROW_COUNT;
    RAISE NOTICE 'spec 054: % intros written', changed;
END
$seed$;
